public void testParseCustom1_1_oe() {
    PeriodFormatter formatter = new PeriodFormatterBuilder()
        .printZeroAlways()
        .appendHours()
        .appendSuffix(":")
        .minimumPrintedDigits(2)
        .appendMinutes()
        .toFormatter();

    Period p;

    p = new Period(47, 55, 0, 0);
    assertEquals("47:55", formatter.print(p));
}

